    {id:'cocaine',name:'Kokain / Cocaine',group:'Tropan alkaloidi',formula:'C₁₇H₂₁NO₄',clues:['N-metilli tropan çekirdeğini ve stereokimyayı kur.','Bir metil karboksilat esteri ekle.','C-3’te benzoiloksi ester bağlantısını ekle; hiyosiyaminin tropat yan zinciriyle karıştırma.'],source:'Coca course deck; Dewick selected Coca pages.'},
    {id:'caffeine',name:'Kafein / Caffeine',group:'Pürin alkaloidi',formula:'C₈H₁₀N₄O₂',clues:['Ksantin/pürin kaynaşık halka sistemini çiz.','İki karbonil grubunu göster.','1,3,7 konumlarındaki üç N-metili ekle; etiketlediğin numaralandırmayı tutarlı kullan.'],source:'Course purine deck; Kogno summ s. 18–19.'},
    {id:'quinoline',name:'Kinolin / Quinoline',group:'Heteroaromatik iskelet',formula:'C₉H₇N',clues:['Bir benzen ve bir piridin halkasını kaynaştır.','Azot piridin halkasında bulunur.','Kinolin çekirdeğini kinin molekülünün tamamıyla karıştırma.'],source:'WhatsApp exam photo Q4; course Cinchona deck.'},
    {id:'indole',name:'İndol / Indole (benzopirol)',group:'Heteroaromatik iskelet',formula:'C₈H₇N',clues:['Benzen halkasını beş üyeli pirol halkasıyla kaynaştır.','Pirol azotunu doğru halkaya yerleştir.','Bu çekirdek tek başına bütün indol alkaloidinin yapısı değildir.'],source:'WhatsApp exam photo Q4; course indole deck.'},
    {id:'codeine',name:'Kodein / Codeine',group:'Morfinan alkaloidi',formula:'C₁₈H₂₁NO₃',clues:['Morfinan iskeletini ve oksijen köprüsünü doğru kur.','Fenolik konumdaki OH’yi metoksiye dönüştür.','Alkol karakterindeki diğer oksijenli grubu ve N-metili koru.'],source:'WhatsApp exam photo Q7; Opium course deck.'},
    {id:'colchicine',name:'Kolşisin / Colchicine',group:'Kolşikum alkaloidi',formula:'C₂₂H₂₅NO₆',clues:['Trisiklik halka düzenini kur; bir halka tropolon karakterlidir.','Metoksi substitüentlerini ve asetamid yan zincirini ekle.','Stereojenik merkezi doğrulanmış çizime göre kontrol et.'],source:'WhatsApp exam photo Q7; Kolşisin 2025 deck.'},
    {id:'lysergic',name:'Lizerjik asit / Lysergic acid',group:'Ergot alkaloidi çekirdeği',formula:'C₁₆H₁₆N₂O₂',clues:['Ergolin/indol içeren kaynaşık halka sistemini kur.','İki azot konumunu dikkatle yerleştir.','C-8 karboksilik asit grubunu göster; amid türeviyle karıştırma.'],source:'WhatsApp exam photo Q7; ergot course slides.'},
    {id:'quinine',name:'Kinin / Quinine — çekirdek alıştırması',group:'Kinolin alkaloidi',formula:'C₂₀H₂₄N₂O₂',clues:['Kinolin halkasını kuinuclidin içeren ikinci bölümle birleştir.','Metoksi, vinil ve sekonder alkol substitüentlerini ekle.','Kinin ve kinidin stereokimyasını kaynak şekliyle karşılaştır.'],source:'Cinchona course deck; Kogno summ s. 16.'},
    {id:'tropine',name:'Tropin / Tropine',group:'Tropan alkaloidi',formula:'C₈H₁₅NO',clues:['N-metilli 8-azabisiklo[3.2.1]oktan iskeletini kur.','C-3’te 3α-hidroksil grubunu yerleştir.','Psödotropinden yalnız adla değil, C-3 OH yönüyle ayır.'],source:'Dewick 2002, pp. 293–295; Kogno summ s. 3–4.'},
    {id:'thebaine',name:'Tebain / Thebaine',group:'Opium morfinan alkaloidi',formula:'C₁₉H₂₁NO₃',clues:['Morfinan/4,5-epoksimorfinan iskeletini kaynak çizimine göre kur.','İki metoksi grubunu doğru oksijenli konumlara ekle.','N-metil ve çizimdeki doymamış bağ/stereokimya düzenini karşılaştır.'],source:'OPIUM 2025 son Türkçe.ppt; WhatsApp exam photo Q4.'},
    {id:'pelletierine',name:'Pelletierin / Pelletierine',group:'Piperidin alkaloidi',formula:'C₈H₁₅NO',clues:['Altı üyeli, bir N içeren piperidin halkasını çiz.','C-2’ye bağlı –CH₂–C(=O)–CH₃ yan zincirini ekle.','Pelletierini izopelletierin ve ψ-pelletierinle aynı yapı sanma.'],source:'PubChem CID 3034881; WhatsApp exam photo Q4.'},    {id:'yohimbine',name:'Yohimbin / Yohimbine',group:'İndol alkaloidi',formula:'C₂₁H₂₆N₂O₃',clues:['İndol alt yapısını bul.','Çok halkalı yohimban iskeletini kur; halka bağlantılarını tahminle kapatma.','Metil ester ve stereomerkezleri doğrulanmış ders yapısıyla denetle.'],source:'WhatsApp exam photo Q7; indole course deck.'}
