  codeine:[5284371,'C₁₈H₂₁NO₃'],colchicine:[6167,'C₂₂H₂₅NO₆'],lysergic:[6717,'C₁₆H₁₆N₂O₂'],quinine:[3034034,'C₂₀H₂₄N₂O₂'],
  tropine:[449293,'C₈H₁₅NO'],thebaine:[5324289,'C₁₉H₂₁NO₃'],pelletierine:[3034881,'C₈H₁₅NO'],yohimbine:[8969,'C₂₁H₂₆N₂O₃']
